#!/usr/bin/env python3
"""Append 2026-09-16 section to trend-index.md at the top of content (after frontmatter)."""
from pathlib import Path
import re

p = Path("indexes/trend-index.md")
text = p.read_text(encoding="utf-8")

# Update last_updated in frontmatter
text = re.sub(
    r"(last_updated: ')\d{4}-\d{2}-\d{2}(')",
    r"\g<1>2026-09-16\g<2>",
    text,
    count=1,
)

# Idempotency
if "## 2026-09-16" in text:
    print("OK (idempotent: today's section already present, skipping)")
    raise SystemExit(0)

# Find end of frontmatter
lines = text.split("\n")
fm_end = 0
for i, l in enumerate(lines):
    if i > 0 and l.strip() == "---":
        fm_end = i + 1
        break

